sys_script_fix.script:
gs.info("*** Migrating SG-Ceburu to the Common Connections Framework ***");

var scopeId = '874c6b7ecffe7a1070a276d42d851c62'; // sys_id of the app
//fetch all SG-Ceburu connections based on parent alias id 
var sysAliasGr = new GlideRecord('sys_alias'); 
sysAliasGr.addQuery('sys_scope', scopeId); 
sysAliasGr.query();

while (sysAliasGr.next()) {
	var common_connection_id = createSgConnectionRecord(sysAliasGr);
	if (!gs.nil(common_connection_id)) {
		//fetch data sources with the given alias sysId
		var dataSourceGr = new GlideRecord('sys_data_source');
		dataSourceGr.addQuery('sys_scope', scopeId);
		dataSourceGr.query();
		var datasourceIDs = [];
		while (dataSourceGr.next()) {
			createCommonConnectionDataSourceRecord(common_connection_id, dataSourceGr.getUniqueValue());
			datasourceIDs.push(dataSourceGr.getUniqueValue());
		}
		//fetch scheduled imports with the given datasourceIDs
		var scheduledImportGr = new GlideRecord('scheduled_import_set'); 
		scheduledImportGr.addQuery('sys_scope', scopeId); 
		scheduledImportGr.addQuery('data_source', 'IN', datasourceIDs); 
		scheduledImportGr.query();

		while (scheduledImportGr.next()) {
			createCommonConnectionScheduledImportRecord(common_connection_id, scheduledImportGr.getUniqueValue());
		}
	} else {
		gs.error("SG-Ceburu connection creation failed for connection alias : " + sysAliasGr.getUniqueValue());
	}
}

// Function creating connection record in the main CCF table and test connection table
function createSgConnectionRecord(connectionAliasGr) {
	var sgConnectionGr = new GlideRecord('x_cesy_service_gr_sg_ceburu_connection');
	sgConnectionGr.addQuery('connection_alias', connectionAliasGr.getUniqueValue());
	sgConnectionGr.query();
	if (!sgConnectionGr.next()) {
		sgConnectionGr.initialize();
		sgConnectionGr.setValue('name', connectionAliasGr.getValue('name'));
		sgConnectionGr.setValue('active', connectionAliasGr.getValue('active'));
		sgConnectionGr.setValue('sys_scope', scopeId);
		sgConnectionGr.setValue('connection_alias', connectionAliasGr.getUniqueValue());
		sgConnectionGr.insert();
	}

	//Add a test script
    var sgTest = new GlideRecord('x_cesy_service_gr_sg_ceburu_connection_test');
    sgTest.addQuery('sys_scope', scopeId);
    sgTest.query();
    if (!sgTest.next()) {
        var SGscript = "new x_cesy_service_gr.SGCeburuConnectionUtil().testConnection(current);";
        sgTest.setValue('sys_scope', scopeId);
        sgTest.setValue('script', SGscript);
        sgTest.insert();
    }

	return sgConnectionGr.getUniqueValue();
}

// Function creating Data Source records in CCF
function createCommonConnectionDataSourceRecord(connectionId, dsSysId) {
	var gr_connection_to_datasource = new GlideRecord('sn_cmdb_int_util_service_graph_connection_data_source');
	gr_connection_to_datasource.addQuery('sn_cmdb_int_util_service_graph_connection', connectionId);
	gr_connection_to_datasource.addQuery('sys_data_source', dsSysId);
	gr_connection_to_datasource.query();
	if (!gr_connection_to_datasource.next()) {
		gr_connection_to_datasource.initialize();
		gr_connection_to_datasource.sn_cmdb_int_util_service_graph_connection = connectionId;
		gr_connection_to_datasource.sys_data_source = dsSysId;
		gr_connection_to_datasource.sys_scope = scopeId;
		gr_connection_to_datasource.insert();
	}
}

// Function creating Scheduled Import records in CCF
function createCommonConnectionScheduledImportRecord(connectionId, siSysId) {
	var gr_connection_to_scheduled_import = new GlideRecord('sn_cmdb_int_util_service_graph_connection_scheduled_data_import');
	gr_connection_to_scheduled_import.addQuery('sn_cmdb_int_util_service_graph_connection', connectionId);
	gr_connection_to_scheduled_import.addQuery('scheduled_import_set', siSysId);
	gr_connection_to_scheduled_import.query();
	if (!gr_connection_to_scheduled_import.next()) {
		gr_connection_to_scheduled_import.initialize();
		gr_connection_to_scheduled_import.sn_cmdb_int_util_service_graph_connection = connectionId;
		gr_connection_to_scheduled_import.scheduled_import_set = siSysId;
		gr_connection_to_scheduled_import.sys_scope = scopeId;
		gr_connection_to_scheduled_import.insert();
	}
}

gs.info("*** Finished migrating SG-Ceburu to the Common Connections Framework ***");
